import axios from 'axios';
import {
    FETCH_EVENTS_REQUEST,
    FETCH_EVENTS_SUCCESS,
    FETCH_EVENTS_FAILURE,
    FETCH_USER_BOOKINGS_REQUEST,
    FETCH_USER_BOOKINGS_SUCCESS,
    FETCH_USER_BOOKINGS_FAILURE,
    SEARCH_EVENTS_REQUEST,
    SEARCH_EVENTS_SUCCESS,
    SEARCH_EVENTS_FAILURE,
} from './userTypes';

// Action to fetch events
export const fetchEvents = () => async (dispatch) => {
    try {
        dispatch({ type: FETCH_EVENTS_REQUEST });

        const { data } = await axios.get('http://localhost:5000/api/events', {
            headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        });

        dispatch({
            type: FETCH_EVENTS_SUCCESS,
            payload: data,
        });
    } catch (error) {
        dispatch({
            type: FETCH_EVENTS_FAILURE,
            payload: error.response && error.response.data.message ? error.response.data.message : error.message,
        });
    }
};

// Action to search events
export const searchEvents = ({ searchTerm, searchField }) => async (dispatch) => {
    try {
        dispatch({ type: SEARCH_EVENTS_REQUEST });

        const { data } = await axios.get(`http://localhost:5000/api/events/search`, {
            params: { term: searchTerm, field: searchField },
            headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        });

        dispatch({
            type: SEARCH_EVENTS_SUCCESS,
            payload: data,
        });
    } catch (error) {
        dispatch({
            type: SEARCH_EVENTS_FAILURE,
            payload: error.response && error.response.data.message ? error.response.data.message : error.message,
        });
    }
};

// Action to fetch user bookings
export const fetchUserBookings = () => async (dispatch) => {
    try {
        dispatch({ type: FETCH_USER_BOOKINGS_REQUEST });

        const { data } = await axios.get('http://localhost:5000/api/user/bookings', {
            headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
